// Pure functions of the browser client, shared with no DOM: formatting as
// the desktop app formats, the colors of events from THEME (theme.js,
// generated by internal/theme), and held-key navigation. internal/viewer's tests run this file in
// Node and compare it with the desktop app's Go: see DESIGN.md.
"use strict";


function trim(v, decimals) {
  if (decimals === 0) return v.toFixed(0);
  const a = Math.abs(v);
  if (a >= 100) decimals = Math.max(decimals - 2, 1);
  else if (a >= 10) decimals = Math.max(decimals - 1, 1);
  let s = v.toFixed(decimals);
  if (s.includes(".")) s = s.replace(/0+$/, "").replace(/\.$/, "");
  return s;
}
function fmtDur(ns) {
  const a = Math.abs(ns);
  if (a < 1e3) return trim(ns, 0) + " ns";
  if (a < 1e6) return trim(ns / 1e3, 3) + " µs";
  if (a < 1e9) return trim(ns / 1e6, 3) + " ms";
  return trim(ns / 1e9, 3) + " s";
}
function fmtTime(ns, nsPerPx) {
  const step = Math.max(nsPerPx * 10, 1);
  let unit = 1e9, name = "s";
  const a = Math.abs(ns);
  if (a < 1e3 && step < 1e3) { unit = 1; name = "ns"; }
  else if (a < 1e6 && step < 1e6) { unit = 1e3; name = "µs"; }
  else if (a < 1e9 && step < 1e9) { unit = 1e6; name = "ms"; }
  const digits = Math.min(9, Math.max(0, Math.ceil(-Math.log10(step / unit))));
  return (ns / unit).toFixed(digits) + " " + name;
}
function tickStep(nsPerPx, minPx) {
  const raw = nsPerPx * minPx;
  if (raw <= 0) return 1;
  const p = Math.pow(10, Math.floor(Math.log10(raw)));
  for (const m of [1, 2, 5, 10]) if (p * m >= raw) return Math.max(p * m, 1);
  return Math.max(p * 10, 1);
}
function fmtTick(ns, step) {
  let unit = 1, name = "ns";
  if (step >= 1e8) { unit = 1e9; name = "s"; }
  else if (step >= 1e5) { unit = 1e6; name = "ms"; }
  else if (step >= 1e2) { unit = 1e3; name = "µs"; }
  const digits = Math.max(0, Math.ceil(-Math.log10(step / unit) - 1e-9));
  return (ns / unit).toFixed(digits) + " " + name;
}
function fmtBytes(b) {
  const k = 1024;
  if (b < k) return b + " B";
  if (b < k * k) return trim(b / k, 2) + " KiB";
  if (b < k * k * k) return trim(b / (k * k), 2) + " MiB";
  return trim(b / (k * k * k), 2) + " GiB";
}
const fmtCount = (n) => n.toLocaleString("en-US");
const compact = (n) => n >= 1e6 ? trim(n / 1e6, 1) + "M" : n >= 1e4 ? trim(n / 1e3, 1) + "k" : fmtCount(n);
function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

// fnv1a is FNV-1a over the UTF-8 bytes of s, as Go's hash/fnv.
function fnv1a(s) {
  let h = 0x811c9dc5;
  for (const b of new TextEncoder().encode(s)) { h ^= b; h = Math.imul(h, 0x01000193) >>> 0; }
  return h >>> 0;
}

const hexRGB = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));

// eventRGB is the color of events named name of kind kind in palette pal
// (THEME.palettes.dark or .light), as the desktop app draws it: memcpy by
// direction, memset in one color, and the others in the hue of their name,
// from the tables THEME computed with MyGo's own OKLCH to sRGB mapping.
function eventRGB(name, kind, pal) {
  const c = pal.colors;
  if (kind === THEME.kindIds.memcpy) {
    return hexRGB(name.includes("HtoD") ? c.memcpyHtoD : name.includes("DtoH") ? c.memcpyDtoH
      : name.includes("DtoD") ? c.memcpyDtoD : name.includes("PtoP") ? c.memcpyPtoP : c.memcpyOther);
  }
  if (kind === THEME.kindIds.memset) return hexRGB(c.memset);
  // A kernel in one of three shades (theme.Shade): apart from its hue.
  const h = fnv1a(name), shade = Math.floor(h / 360) % 3;
  let tone = THEME.kindTones[kind] || "other";
  if (tone === "kernel" && shade) tone += "." + shade;
  const table = pal.hues[tone], i = (h % 360) * 3;
  return [table[i], table[i + 1], table[i + 2]];
}

// Navigation with held keys, as the desktop app's (internal/viewer/nav.go):
// navTargets is the speeds the keys held ask for (pan in view widths a
// second, zoom in natural log of the scale a second, positive out; speed
// is the navigation speed setting, a multiplier), and
// navAdvance eases the speeds toward them over dt seconds, returning the
// new speeds and how far they move the view meanwhile.
function navTargets(left, right, zoomIn, zoomOut, shift, speed) {
  const n = THEME.nav;
  let pan = 0, zoom = 0;
  if (right) pan += n.pan;
  if (left) pan -= n.pan;
  if (zoomOut) zoom += n.zoom;
  if (zoomIn) zoom -= n.zoom;
  if (shift) { pan *= n.shift; zoom *= n.shift; }
  return [pan * speed, zoom * speed];
}
function navAdvance(vPan, vZoom, tPan, tZoom, dt) {
  const k = 1 - Math.exp(-dt / THEME.nav.ease);
  let np = vPan + (tPan - vPan) * k, nz = vZoom + (tZoom - vZoom) * k;
  if (tPan === 0 && Math.abs(np) < 0.02 * THEME.nav.pan) np = 0;
  if (tZoom === 0 && Math.abs(nz) < 0.02 * THEME.nav.zoom) nz = 0;
  return [np, nz, (vPan + np) / 2 * dt, (vZoom + nz) / 2 * dt];
}

// The rank overview (as internal/viewer/compact.go): compactLayout lays out
// traces, each given as how many sub-lanes the summary lane of each kind of
// its rows has ({stream: 3, nvtx: 2}), with the summary lanes of keys in
// on: per trace a busy/idle strip, then the sub-lanes of each lane, in
// THEME.compactLanes' order. It returns the rows, {trace, key ("" for the
// strip), sub, y, h}, and the height of them all.
function compactLayout(subs, on) {
  const M = THEME.metrics, rows = [];
  let y = 0;
  subs.forEach((ks, ti) => {
    if (ti > 0) y += M.compactGap;
    rows.push({ trace: ti, key: "", sub: 0, y, h: M.compactStripH });
    y += M.compactStripH;
    let first = true;
    for (const l of THEME.compactLanes) {
      const n = ks[l.kind] || 0;
      if (!on.includes(l.key) || n <= 0) continue;
      if (!first) y += M.compactKindGap;
      first = false;
      for (let sub = 0; sub < n; sub++) {
        rows.push({ trace: ti, key: l.key, sub, y, h: M.compactLaneH });
        y += M.compactLaneH;
      }
    }
  });
  return { rows, height: y };
}
// trackLane is the height of a lane of a row of kind ("stream", "api",
// "nvtx", ...) and the space above and below its lanes, [lh, pad]: GPU
// streams and CUDA API calls are denser than the others. As
// internal/viewer/compact.go's.
function trackLane(kind) {
  const M = THEME.metrics;
  return kind === "stream" || kind === "api" ? [M.denseLaneH, M.densePad] : [M.laneH, M.trackPad];
}
// trackHeight is the height of a row of kind with lanes lanes.
function trackHeight(kind, lanes) {
  const [lh, pad] = trackLane(kind);
  return Math.max(lanes, 1) * lh + 2 * pad;
}
// laneSlot is the sub-lane of its kind's summary lane that lane li of a row
// (of kind "stream", "api" or "nvtx", of lanes lanes) draws into, or -1 if
// none: where the trace's overview puts it when stacked (or, without one,
// the first: every lane of a stream, the outermost of the others), the
// first when overlaid.
function laneSlot(kind, lanes, overview, li, stacked) {
  if (li >= lanes) return -1;
  if (stacked && overview) return li < overview.length ? overview[li] : -1;
  return kind === "stream" || li === 0 ? 0 : -1;
}
// traceFilter is how a session's link says which of its traces (by key,
// traceBase) are left out (off): ["only", the keys of those shown] if
// fewer, else ["omit", the keys of those left out]; ["", []] if none is.
// As internal/viewer/compact.go's.
function traceFilter(keys, off) {
  const shown = keys.filter((k, i) => !off[i]), omitted = keys.filter((k, i) => !!off[i]);
  if (!omitted.length) return ["", []];
  return shown.length < omitted.length ? ["only", shown] : ["omit", omitted];
}
// filterOff is which traces (by key) a link's only and omit leave out:
// with only, those it does not name; else those omit names. None if that
// would be every trace.
function filterOff(keys, only, omit) {
  const off = keys.map((k) => only.length ? !only.includes(k) : omit.includes(k));
  return off.every(Boolean) ? off.map(() => false) : off;
}
// tabTitle names a tab by the paths it was opened with (as
// internal/viewer/compact.go's): the first one's last element, without a
// trace file's extension, and how many more; "New tab" for none.
function tabTitle(inputs) {
  if (!inputs || !inputs.length) return "New tab";
  return inputs.length > 1 ? `${traceBase(inputs[0])} +${inputs.length - 1}` : traceBase(inputs[0]);
}
// traceBase is the last element of a path without a trace file's ending
// (an nsys export or report, a PyTorch profiler's JSON): "rank0" of
// "/runs/rank0.pt.trace.json". As the desktop app's.
function traceBase(p) {
  const m = /#rank(\d+)$/.exec(p); // a rank of a merged file
  if (m) return "rank" + m[1];
  const s = p.replace(/[\/\\]+$/, "");
  let b = s.slice(Math.max(s.lastIndexOf("/"), s.lastIndexOf("\\")) + 1);
  if (!b) b = p;
  return b.replace(/(.)\.(sqlite|nsys-rep|qdrep|pt\.trace\.json\.gz|pt\.trace\.json|json\.gz|json)$/i, "$1");
}
// busyColumns is the share of each of n pixel columns from time t0 at
// scale ns a pixel that blocks ([start, end, busy] triples, flat) keep
// busy: each block's density spread over the columns it covers, capped at 1.
// (out, if given, is reused.)
function busyColumns(blocks, t0, scale, n, out) {
  out = out || [];
  n = Math.max(n, 0); // a window narrower than the label gutter
  out.length = n;
  out.fill(0);
  for (let i = 0; i + 2 < blocks.length; i += 3) {
    const s = blocks[i], e = blocks[i + 1], busy = blocks[i + 2];
    const d = e > s ? Math.min(busy / (e - s), 1) : 1;
    const c0 = Math.max(Math.floor((s - t0) / scale), 0), c1 = Math.min(Math.floor((e - t0) / scale), n - 1);
    for (let c = c0; c <= c1; c++) {
      const a = Math.max(s, t0 + c * scale), b = Math.min(e, t0 + (c + 1) * scale);
      out[c] += e > s ? d * Math.max(b - a, 0) / scale : 1 / 3;
    }
  }
  for (let c = 0; c < n; c++) out[c] = Math.min(out[c], 1);
  return out;
}

// alignTraces puts the traces of a session on one time axis (as
// internal/viewer/align.go, which explains it): each {utc, mono, host,
// start} (capture start on the wall clock and on the host's monotonic
// clock, 0 if unknown; first event's time from the capture's start) gets
// {offset, basis}: where its first event is, the earliest at 0, by "wall"
// (its wall clock), "host" (another trace of its host's, through the
// host's monotonic clock), "monotonic" (its host's clock, among the host's
// traces only) or "start" (at 0; also every trace in mode "start").
// hostOf is what traces go together by their monotonic clocks: their host,
// or where there is none, their clock's (several ranks merged into one
// file). As align.go's clockHosts.
const hostOf = (t) => t.host || (t.clock ? "\u0000" + t.clock : "");
const clockHosts = (ts) => ts.map((t) => (t.host || !t.clock ? t : { ...t, host: hostOf(t) }));
function alignTraces(ts, mode) {
  ts = clockHosts(ts);
  const out = ts.map(() => ({ offset: 0, basis: "start" }));
  if (mode !== "abs") return out;
  // Wall clocks relative to the earliest (exact, where ns since 1970 are
  // not, in doubles), +1 so that 0 says "none".
  let ref = Infinity;
  for (const t of ts) if (t.utc > 0) ref = Math.min(ref, t.utc);
  const wall = ts.map((t, i) => { if (t.utc > 0) { out[i].basis = "wall"; return t.utc - ref + 1; } return 0; });
  ts.forEach((t, i) => {
    if (wall[i] !== 0 || !(t.mono > 0) || !t.host) return;
    const r = ts.find((r) => r.host === t.host && r.utc > 0 && r.mono > 0);
    if (r) { wall[i] = r.utc - ref + 1 + (t.mono - r.mono); out[i].basis = "host"; }
  });
  let origin = Infinity;
  ts.forEach((t, i) => { if (wall[i] !== 0) origin = Math.min(origin, wall[i] + t.start); });
  ts.forEach((t, i) => { if (wall[i] !== 0) out[i].offset = wall[i] + t.start - origin; });
  ts.forEach((t, i) => {
    if (wall[i] !== 0 || !(t.mono > 0) || !t.host || out[i].basis === "monotonic") return;
    let m0 = Infinity;
    ts.forEach((u, j) => { if (wall[j] === 0 && u.host === t.host && u.mono > 0) m0 = Math.min(m0, u.mono + u.start); });
    ts.forEach((u, j) => { if (wall[j] === 0 && u.host === t.host && u.mono > 0) out[j] = { offset: u.mono + u.start - m0, basis: "monotonic" }; });
  });
  return out;
}

// alignSession is alignTraces refined by collective kernels in mode
// "collectives" (as internal/viewer/align.go, which explains it): each
// trace moved so that its collectives' ends ({op: [ns from its first
// event, sorted]} in coll) meet the reference trace's, with {matches,
// spread, ref} on those it moved; "abs" and "start" are alignTraces'.
const COLL = { min: 8, bin: 100e3, sample: 400, near: 20e6, windows: [5e6, 1e6, 200e3] };
function alignSession(ts, mode) {
  ts = clockHosts(ts);
  const out = alignTraces(ts, mode === "start" ? "start" : "abs");
  if (mode !== "collectives") return out;
  const total = (i) => Object.values(ts[i].coll || {}).reduce((n, v) => n + v.length, 0);
  const ref = ts.findIndex((_, i) => total(i) >= COLL.min);
  if (ref < 0) return out;
  const wallish = (x) => x === "wall" || x === "host";
  const comparable = (i) => {
    const a = out[i].basis, b = out[ref].basis;
    return (wallish(a) && wallish(b)) || (a === "monotonic" && b === "monotonic" && ts[i].host === ts[ref].host);
  };
  const refOff = out[ref].offset;
  let any = false;
  ts.forEach((_, i) => {
    if (i === ref || total(i) < COLL.min) return;
    const m = matchCollectives(ts[ref].coll, ts[i].coll, out[i].offset - refOff, comparable(i));
    if (m) { out[i] = { offset: refOff + m.off, basis: "collectives", matches: m.matches, spread: m.spread }; any = true; }
  });
  if (any) out[ref] = { offset: refOff, basis: "collectives", ref: true };
  const lo = Math.min(...out.map((o) => o.offset));
  for (const o of out) o.offset -= lo;
  return out;
}
function nearestIn(v, x) {
  let lo = 0, hi = v.length; // the first index with v[i] >= x
  while (lo < hi) { const m = (lo + hi) >> 1; if (v[m] < x) lo = m + 1; else hi = m; }
  let i = lo;
  if (i === v.length || (i > 0 && x - v[i - 1] <= v[i] - x)) i--;
  return i;
}
function collOps(a, b) {
  return Object.keys(a || {}).filter((op) => a[op].length > 0 && (b || {})[op] && b[op].length > 0).sort();
}
function collDiffs(a, b, ops, off, w) {
  const d = [];
  for (const op of ops) {
    const bs = b[op];
    for (const x of a[op]) {
      const diff = x - (bs[nearestIn(bs, x - off)] + off);
      if (Math.abs(diff) < w) d.push(diff);
    }
  }
  return d.sort((x, y) => x - y);
}
// matchCollectives finds how far to move b's times so that its collectives
// end with a's: {off, matches, spread}, or null if too few match.
function matchCollectives(a, b, guess, haveGuess) {
  const ops = collOps(a, b);
  if (!ops.length) return null;
  let na = 0, nb = 0;
  for (const op of ops) { na += a[op].length; nb += b[op].length; }
  const need = Math.max(COLL.min, Math.ceil(0.2 * Math.min(na, nb)));
  let off;
  {
    const hist = new Map();
    for (const op of ops) {
      const as = a[op].slice(0, COLL.sample), bs = b[op].slice(0, COLL.sample);
      for (const x of as) for (const y of bs) {
        if (haveGuess && Math.abs(x - y - guess) > COLL.near) continue;
        const k = Math.floor((x - y) / COLL.bin);
        hist.set(k, (hist.get(k) || 0) + 1);
      }
    }
    if (!hist.size) return null;
    let best = 0, bestN = -1;
    for (const k of [...hist.keys()].sort((x, y) => x - y)) if (hist.get(k) > bestN) { best = k; bestN = hist.get(k); }
    off = (best + 0.5) * COLL.bin;
  }
  for (const w of COLL.windows) {
    const d = collDiffs(a, b, ops, off, w);
    if (!d.length) return null;
    off += d[d.length >> 1];
  }
  const d = collDiffs(a, b, ops, off, COLL.windows[COLL.windows.length - 1]);
  if (d.length < need) return null;
  const abs = d.map(Math.abs).sort((x, y) => x - y);
  return { off, matches: d.length, spread: abs[Math.min(abs.length - 1, Math.floor(0.9 * abs.length))] };
}
